<?php

  // correlate - Input `{a:[...],b:[...]}`. r[k]=sum_i a[i]×b[i+k], lags −(N−1)..M−1, optionally restricted by maxLag. Positive lag means b is delayed. No implicit mean removal. normalization none (default), biased (divide by max(N,M)), unbiased (divide by overlap count), coefficient (global Euclidean norms). Zero-energy coefficient input returns degenerate. Coefficient scaling is normalized before multiplication to limit overflow. With sampleRate, lagSeconds is reported.
  //
  // `padSignal('correlate',['a'=>[1,0,0],'b'=>[0,0,1]],['sampleRate'=>10,'normalization'=>'none'])`

return ['options'=>['normalization','maxLag','sampleRate'],'call'=>function($input,$options,&$state){if(!is_array($input)||array_diff(array_keys($input),['a','b']))throw new InvalidArgumentException('correlate input needs a and b');$a=padSignalSamples($input['a']??NULL,$state);$b=padSignalSamples($input['b']??NULL,$state);$n=count($a);$m=count($b);$mode=$options['normalization']??'none';$lag=$options['maxLag']??max($n,$m)-1;$rate=padSignalRate($options);if(!in_array($mode,['none','biased','unbiased','coefficient'],TRUE)||!is_int($lag)||$lag<0||$lag>4095)throw new InvalidArgumentException('normalization is none/biased/unbiased/coefficient; maxLag 0..4095');$norm=1.0;
 if($mode==='coefficient'){$sa=max(array_map('abs',$a));$sb=max(array_map('abs',$b));if($sa==0||$sb==0)return ['status'=>'degenerate','values'=>[],'lags'=>[],'normalization'=>$mode,'sampleRate'=>$rate];$a=array_map(fn($v)=>$v/$sa,$a);$b=array_map(fn($v)=>$v/$sb,$b);$norm=sqrt(array_sum(array_map(fn($v)=>$v*$v,$a)))*sqrt(array_sum(array_map(fn($v)=>$v*$v,$b)));}
 $out=[];$lags=[];$overlaps=[];for($k=max(-$n+1,-$lag);$k<=min($m-1,$lag);$k++){$sum=$c=0.0;$lo=max(0,-$k);$hi=min($n-1,$m-1-$k);for($i=$lo;$i<=$hi;$i++){padSignalTick($state);padSignalAccumulate($sum,$c,$a[$i]*$b[$i+$k]);}$overlap=$hi-$lo+1;$den=match($mode){'biased'=>max($n,$m),'unbiased'=>$overlap,'coefficient'=>$norm,default=>1};$value=$sum/$den;if($mode==='coefficient')$value=max(-1.0,min(1.0,$value));$out[]=$value;$lags[]=$k;$overlaps[]=$overlap;}
 return ['status'=>'ok','values'=>$out,'lags'=>$lags,'lagSeconds'=>$rate===NULL?NULL:array_map(fn($k)=>$k/$rate,$lags),'overlapCounts'=>$overlaps,'normalization'=>$mode,'sampleRate'=>$rate,'definition'=>'r[k] = sum_i a[i] * b[i+k]; positive lag means b is delayed relative to a'];}];
